def constrainedSubsetSum(nums: list[int], k: int) -> int:
    from collections import deque
    dp = list(nums)
    q = deque()
    for i in range(len(nums)):
        if q and q[0] < i - k:
            q.popleft()
        if q:
            dp[i] = max(dp[i], dp[i] + dp[q[0]])
        while q and dp[q[-1]] <= dp[i]:
            q.pop()
        q.append(i)
    return max(dp)

